/// Batch descriptors preserve nullability in the build-time model just as the
/// individual API does, including const values, local imports and macro tables.
#[test]
fn nullable_batch_descriptors_are_read_and_unread_entries_are_counted() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/nullable_registration/lib.rs");
    let scan = scan_crate(&ScanOptions::new("nullable_registration", root));
    let registrations: Vec<(&str, Vec<&str>)> = scan.model.value_types.iter().map(|value| {
        (value.registration.as_str(), value.types.iter().map(|type_| type_.text.as_str()).collect())
    }).collect();
    assert_eq!(registrations, [
        ("nullable", vec!["i64"]),
        ("nullable", vec!["::std::rc::Rc<dyn ::nullable_registration::IServiceProvider>"]),
        ("nullable", vec!["::std::rc::Rc<::nullable_registration::Model>"]),
        ("nullable", vec!["String"]),
        ("nullable", vec!["u8"]),
        ("nullable", vec!["u16"]),
    ], "{}", listing(&scan.diagnostics));
    assert!(scan.model.value_types.iter().all(|value| value.types.iter().all(RustType::is_resolved)));

#[cfg(test)]
mod nullable_descriptor_tests {
    use super::*;

    #[test]
    fn nullable_descriptors_in_declaration_tokens_use_the_canonical_registration() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/nullable_registration/lib.rs");
        let mut source = Source::read(&ScanOptions::new("nullable_registration", root));
        let before = source.value_types.len();
        let read = source.value_calls.get("nullable").map_or(0, |value| value.1);
        let tokens = tokens_of("ValueTypes::register_nullable_types(&const { [NullableRegistration::of::<Rc<dyn IServiceProvider>>()] });".parse().unwrap());
        source.read_registrations_of_tokens(&tokens, &Site { module: 0, file: 0, line: 1, cfg: Vec::new(), expanded: false });
        let entries = &source.value_types[before..];
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].value.registration, "nullable");
        assert_eq!(text_of(&entries[0].value.types[0]), "Rc<dyn IServiceProvider>");
        assert_eq!(source.value_calls.get("nullable").unwrap().1, read + 1);
    }
}

//! Scanner-only fixture for the typed descriptors consumed by batch registration.
use ferroui_base::data::core::{NullableRegistration, ValueTypes};
use std::rc::Rc;

pub trait IServiceProvider {}
pub struct Model;

// Named tables carry the same type information as inline const arrays. The
// source scanner describes potential registrations, not runtime reachability.
const NAMED: &[NullableRegistration] = &[NullableRegistration::of::<i64>()];

fn register() {
    use crate::Model as LocalModel;
    ValueTypes::register_nullable_types(NAMED);
    ValueTypes::register_nullable_types(&const { [
        NullableRegistration::of::<Rc<dyn IServiceProvider>>(),
        ferroui_base::data::core::NullableRegistration::of::<Rc<LocalModel>>(),
    ] });

