"""Capture the small retained harness/recipe sources without touching build artifacts."""

import hashlib
import json
from pathlib import Path
import re
import subprocess


MAX_TEXT_BYTES = 1024 * 1024
PATH_MODULE = re.compile(r'#\[path\s*=\s*"([^"\n]+)"\]\s*(?:pub(?:\([^)]*\))?\s+)?mod\s+\w+\s*;')


def build_source_appendix(records, final_phase, repo, run, qa, original_data=None, evidence=None):
    """Deduplicate exact UTF-8 text, preserving paths and the scope of old hash claims."""
    sources, locations, dependencies, claims, module_claims, helper_claims, issues, pending = {}, {}, [], [], [], [], [], []
    cache = {}

    def read(path):
        path = Path(path)
        if path not in cache:
            before = path.stat()
            if before.st_size > MAX_TEXT_BYTES:
                raise ValueError(f'text input exceeds the small-source limit: {path}')
            blob = path.read_bytes()
            after = path.stat()
            if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
                raise ValueError(f'text input changed during capture: {path}')
            cache[path] = blob
        return cache[path]

    def retain(blob, path, role, artifact=None, pointer=None):
        text = blob.decode('utf-8')
        sha = hashlib.sha256(blob).hexdigest()
        sources.setdefault(sha, {'bytes': len(blob), 'encoding': 'utf-8', 'text': text})
        key = str(path) + ('#' + pointer if pointer else '')
        location = locations.setdefault(key, {'path': str(path), 'sha256': sha,
                                              'bytes': len(blob), 'roles': [], 'artifact_ids': [],
                                              'capture_scope': 'Text retained at source capture; historical usage requires an explicit matching producer hash claim.'})
        if location['sha256'] != sha:
            raise ValueError(f'source location changed during capture: {key}')
        if pointer:
            location['json_pointer'] = pointer
        if role not in location['roles']:
            location['roles'].append(role)
        if artifact and artifact not in location['artifact_ids']:
            location['artifact_ids'].append(artifact)
        return sha, location

    def add(path, role, artifact=None, follow_modules=False):
        path = Path(path)
        blob = read(path)
        sha, location = retain(blob, path, role, artifact)
        candidates = []
        for root in (repo, Path('/tmp/ferro496-base')):
            try:
                candidates.append(path.relative_to(root))
            except ValueError:
                pass
        if path.parent == qa:
            candidates.append(Path('src/FerroUI.Base/tests') / path.name)
        for relative in candidates:
            target = repo / relative
            if target.is_file() and read(target) == blob:
                location['repository_path'] = str(relative)
                location['repository_mapping_scope'] = 'Byte-identical to the repository file at source capture.'
                break
        if follow_modules:
            for match in PATH_MODULE.finditer(blob.decode('utf-8')):
                child = Path(match.group(1))
                if not child.is_absolute():
                    child = path.parent / child
                edge = {'parent_path': str(path), 'child_path': str(child), 'mechanism': 'Rust #[path] module'}
                if edge not in dependencies:
                    dependencies.append(edge)
                    add(child, 'Rust module dependency', artifact, True)
        return sha

    # Existing file-reference evidence remains intact and gains a source appendix entry.
    for record in records:
        if record['kind'] == 'file_reference' and record['path']:
            path = Path(record['path'])
            if path.suffix in ('.py', '.rs', '.patch'):
                if not path.is_file() and record['phase'].startswith(('stage3_', 'stage4_')):
                    pending.append({'artifact': record['id'], 'path': str(path),
                                    'reason': 'source producer has not supplied this configured file yet'})
                    continue
                add(path, 'retained recipe or source patch', record['id'], path.suffix == '.rs')

    for name in ('assemble.py', 'source_appendix.py', f'{final_phase}-paths.json'):
        add(Path(__file__).resolve().parent / name,
            'evidence assembly recipe/configuration; not a measured runtime input')

    add(qa / 'qa.rs', 'shared QA entry and ignored seven-lane timing entry; test count depends on configuration', follow_modules=True)
    add(run / 'final-registry-tests.rs', 'final registry harness', follow_modules=True)
    for phase in ('stage2', 'stage3') + (('stage4',) if final_phase == 'stage4' else ()):
        add(run / f'{phase}-registry-tests.rs', 'phase registry harness', f'{phase}.registry', True)
        add(run / f'bench-bindings-{phase}.py', 'binding measurement recipe', f'{phase}.bindings_cpu6')
        add(run / f'verify-{phase}.py', 'registry and unwind compile/run recipe', f'{phase}.registry')
    add(run / 'unwind_compatibility.rs', 'compact-unwind compatibility probe')
    for path, role, artifact in (
            (Path('/tmp/recover-xaml/property-runner.py'), 'QA replay compiler/runner', None),
            (run / 'run-final-qa.py', 'phase-specific QA runner', None),
            (run / 'bench-bindings-current.py', 'binding measurement recipe', 'combined.bindings_cpu6'),
            (run / 'bench-bindings-latest.py', 'binding measurement recipe', 'latest484.bindings_cpu6'),
            (Path('/tmp/ferro496-conversion-recovery/measure-trial.py'), 'Base-only diagnostic fixture driver', None),
            (Path('/tmp/ferro496-base/scripts/themes/bench/measure.py'), 'startup measurement import', None)):
        add(path, role, artifact)
    for name in ('compare_registration.py', 'registration_hot_paths.rs', 'interface_registration.rs',
                 'compact_unwind_link.py', 'compact_unwind.py', 'attribute_codegen.py', 'measure.py', 'winui.rs'):
        add(repo / 'scripts/themes/bench' / name, 'repository benchmark source/helper')
    if final_phase == 'stage4':
        for name in ('winui.rs', 'pgo_templates.rs'):
            add(Path('/tmp/ferro496-base/scripts/themes/bench') / name,
                'template companion derivation input; exact companion text is retained separately')
    for trial in ('inline-id-hash-trial', 'inline-clone-trial'):
        add(run / trial / 'registration/capture-cc.py', 'generated diagnostic CC wrapper')
    for directory in (run / 'registration-stage3', run / 'registration-stage4'):
        if directory.is_dir():
            for wrapper in sorted(directory.glob('*.native/capture-cc.py')):
                add(wrapper, 'generated registration CC wrapper')
    recovered_driver = Path(__file__).resolve().parent / 'recovered/compare_registration.py'
    recovered_sha = add(recovered_driver, 'recovered historical registration helper', 'inline_hash.fixture_build')
    if recovered_sha != 'd971f03f13c9a61dbfd64ec47d3a0431f8e0735f3e3e85e1cf892f7dd795cf95':
        raise ValueError('recovered registration helper differs from its recorded diagnostic identity')
    locations[str(recovered_driver)]['recovery'] = {
        'method': 'Reverse only the native-capture additions from the retained current driver; verify the entire resulting file against the original recorded SHA256.',
        'original_helper_name': 'compare_registration.py',
        'original_benchmark_directory': str(repo / 'scripts/themes/bench'),
        'artifact': 'inline_hash.fixture_build',
        'json_pointer': '/identity/helper_sha256/compare_registration.py',
    }

    # The old QA report contains the actual extraction recipe, not just source hashes.
    replay_path = repo / 'docs/benchmarks/compiled-theme-binding-abi-linux-x86_64.json'
    replay_blob = read(replay_path)
    replay = json.loads(replay_blob)['replay']
    materializer_sha, _ = retain(replay['materialize_python'].encode('utf-8'), replay_path,
                                 'original QA materialization recipe', pointer='/replay/materialize_python')
    reconstructed, original_comparison = {}, []
    for name, recipe in replay['fixture'].items():
        if 'literal' in recipe:
            content = recipe['literal']
        else:
            blob_id = recipe['git_blob']
            if not re.fullmatch('[0-9a-f]{40,64}', blob_id):
                raise ValueError(f'invalid QA recipe git blob: {name}')
            blob = subprocess.check_output(['git', 'cat-file', 'blob', blob_id], cwd=repo)
            lines = blob.decode('utf-8').splitlines(keepends=True)
            content = ''.join(part if isinstance(part, str) else ''.join(lines[part[0]:part[1]])
                              for part in recipe['parts'])
        expected = content.replace('@FIXTURE@', str(qa)).encode('utf-8')
        actual = read(qa / name)
        if expected != actual:
            raise ValueError(f'QA materialization recipe no longer matches retained input: {name}')
        reconstructed[name] = hashlib.sha256(actual).hexdigest()
        original_sha = replay['as_built_source_sha256'][name]
        original_comparison.append({'name': name, 'original_as_built_sha256': original_sha,
                                    'retained_reconstruction_sha256': reconstructed[name],
                                    'matches_original_as_built': original_sha == reconstructed[name],
                                    'recipe_uses_fixture_placeholder': '@FIXTURE@' in content})
    materialization = {
        'path': str(replay_path), 'repository_path': str(replay_path.relative_to(repo)),
        'sha256': hashlib.sha256(replay_blob).hexdigest(), 'json_pointer': '/replay',
        'materialize_python_sha256': materializer_sha, 'fixture_recipe_pointer': '/replay/fixture',
        'replacement': {'@FIXTURE@': str(qa)}, 'exact_reconstruction_sha256': reconstructed,
        'original_as_built_source_sha256': replay['as_built_source_sha256'],
        'original_as_built_hash_comparison': {
            'matching_entries': sum(row['matches_original_as_built'] for row in original_comparison),
            'different_entries': [row for row in original_comparison if not row['matches_original_as_built']],
            'scope': 'Exact reconstruction uses the retained fixture directory. It does not assert byte equality to all original as-built hashes; the two path-bearing wrapper files have different hashes after fixture-path substitution.',
        },
        'rustc_flags': replay['rustc_flags'],
        'scope': 'The existing repository recipe reproduces all retained 21-file QA inputs exactly at the recorded fixture path. registration.rs belongs to the separate registry harness.',
    }

    # Check entry-source claims only where a producer actually recorded a hash.
    # Module snapshot hashes are not retroactively attributed to old build manifests.
    def visit(value, artifact, pointer=''):
        if isinstance(value, dict):
            for name in ('source', 'recipe'):
                identity = value.get(name)
                if not isinstance(identity, dict) or not {'path', 'sha256'} <= identity.keys():
                    continue
                path, expected = identity['path'], identity['sha256']
                if not isinstance(path, str) or Path(path).suffix not in ('.rs', '.py', '.patch'):
                    continue
                actual = add(path, 'text input identified by a producer', artifact, path.endswith('.rs'))
                claim = {'artifact': artifact, 'json_pointer': pointer + '/' + name + '/sha256',
                         'recorded_path': path, 'recorded_sha256': expected,
                         'retained_sha256': actual, 'matches_recorded_hash': actual == expected}
                claims.append(claim)
                if actual != expected:
                    issues.append({**claim, 'reason': 'retained text differs from producer input identity'})
            for field in ('driver_sha256', 'capture_wrapper_sha256', 'recipe_sha256'):
                if field in value:
                    helper_claims.append({'artifact': artifact, 'json_pointer': pointer + '/' + field,
                                          'recorded_sha256': value[field], 'helper': field})
            for field in ('helper_sha256', 'linker_source_sha256'):
                if isinstance(value.get(field), dict):
                    for name, sha in value[field].items():
                        helper_claims.append({'artifact': artifact,
                                              'json_pointer': pointer + '/' + field + '/' + name,
                                              'recorded_sha256': sha, 'helper': name})
            capture = value.get('native_capture')
            if isinstance(capture, dict) and isinstance(capture.get('wrapper'), dict):
                wrapper = capture['wrapper']
                add(wrapper['path'], 'generated registration CC wrapper', artifact)
                helper_claims.append({'artifact': artifact,
                                      'json_pointer': pointer + '/native_capture/wrapper/sha256',
                                      'recorded_path': wrapper['path'], 'recorded_sha256': wrapper['sha256'],
                                      'helper': 'native_capture_wrapper'})
            for hash_field, command_field in (('source_sha256', 'command'), ('qa_source_sha256', 'qa_command')):
                expected = value.get(hash_field)
                if not isinstance(expected, str) or not re.fullmatch('[0-9a-f]{64}', expected):
                    continue
                path = value.get('source') if hash_field == 'source_sha256' else None
                if not isinstance(path, str):
                    command = value.get(command_field, value.get('cmd', []))
                    roots = [item for item in command if isinstance(item, str) and item.endswith('.rs')
                             and not item.startswith('-')]
                    path = roots[0] if len(roots) == 1 else None
                if path:
                    claim = {'artifact': artifact, 'json_pointer': pointer + '/' + hash_field,
                             'recorded_path': path, 'recorded_sha256': expected}
                    try:
                        actual = add(path, 'entry source named by a build manifest', artifact, path.endswith('.rs'))
                        claim['retained_sha256'] = actual
                        claim['matches_recorded_hash'] = actual == expected
                        if actual != expected:
                            issues.append({**claim, 'reason': 'current retained text differs from recorded build source'})
                    except OSError as error:
                        claim['matches_recorded_hash'] = False
                        issues.append({**claim, 'reason': str(error)})
                    claims.append(claim)
            if isinstance(value.get('qa_source_hashes'), dict):
                for path, expected in value['qa_source_hashes'].items():
                    actual = add(path, 'QA directory input hashed by its producer', artifact, path.endswith('.rs'))
                    claim = {'artifact': artifact,
                             'json_pointer': pointer + '/qa_source_hashes/' + path.replace('~', '~0').replace('/', '~1'),
                             'recorded_path': path, 'recorded_sha256': expected, 'retained_sha256': actual,
                             'matches_recorded_hash': actual == expected,
                             'scope': 'Producer-hashed QA directory input; Rust module edges identify which entry uses it.'}
                    module_claims.append(claim)
                    if actual != expected:
                        issues.append({**claim, 'reason': 'retained QA input differs from producer-hashed source'})
            for key, child in value.items():
                visit(child, artifact, pointer + '/' + str(key).replace('~', '~0').replace('/', '~1'))
        elif isinstance(value, list):
            for index, child in enumerate(value):
                if isinstance(child, (dict, list)):
                    visit(child, artifact, pointer + '/' + str(index))

    for artifact, data in (original_data or {}).items():
        visit(data, artifact)
        if artifact.endswith('.inline_producers'):
            for item in data['files'].values():
                actual = add(item['path'], 'retrospectively retained inline orchestration', artifact)
                if actual != item['sha256']:
                    raise ValueError(f'retained inline producer differs from its retention record: {item["path"]}')
                locations[item['path']]['retention_provenance'] = {
                    'artifact': artifact, 'reported_execution_mode': data['execution_mode'],
                    'scope': 'This is an after-execution source retention record, not a file hash captured when the inline producer ran.',
                }
    for claim in helper_claims:
        sha = claim['recorded_sha256']
        claim['retained_exact_text'] = sha in sources
        if sha not in sources:
            issues.append({**claim, 'reason': 'no retained helper text matches the recorded historical SHA'})
    for claim in claims + module_claims + helper_claims:
        sha = claim['recorded_sha256']
        if sha in sources:
            record = {key: claim[key] for key in ('artifact', 'json_pointer', 'recorded_path') if key in claim}
            sources[sha].setdefault('producer_hash_claims', []).append(record)
    for record in records:
        if record['kind'] != 'file_reference' or not record['path']:
            continue
        location = locations.get(record['path'])
        item = (evidence or {}).get(record['id'])
        if location and item and item.get('available'):
            if location['sha256'] != item['sha256']:
                raise ValueError(f'recipe source differs from evidence identity: {record["id"]}')
            item['source_text_sha256'] = location['sha256']

    return {
        'sources_by_sha256': sources,
        'source_locations': locations,
        'source_dependencies': dependencies,
        'recorded_entry_source_claims': claims,
        'recorded_module_source_claims': module_claims,
        'recorded_helper_source_claims': helper_claims,
        'entry_source_claims_evaluated': original_data is not None,
        'unresolved_recorded_sources': issues,
        'pending_source_locations': pending,
        'qa_materialization': materialization,
        'source_summary': {'unique_texts': len(sources), 'locations': len(locations),
                           'unique_utf8_bytes': sum(item['bytes'] for item in sources.values()),
                           'location_utf8_bytes_before_deduplication': sum(item['bytes'] for item in locations.values()),
                           'rust_module_edges': len(dependencies)},
        'source_scope': [
            'Exact retained UTF-8 source text is stored once per SHA256. Paths and absolute Rust module attributes remain unchanged.',
            'Temporary paths are original provenance, not portable locations. Reproduction must restore or consistently remap those paths and supply the separately recorded toolchain, profile and library graph.',
            'A matches_recorded_hash claim covers only the entry file actually hashed by that manifest. Dependent-module hashes are retained snapshot identities, not new claims that old manifests hashed them.',
            'Saved Python recipe text is capture-time evidence unless the appendix lists a matching producer hash claim for that exact body. Current recipe text is never silently substituted for a different historical helper hash.',
            'The original 21-file QA extraction recipe is preserved in an existing repository report and its exact reconstruction was checked. The extra registry input and bespoke timing/verification scripts are retained directly as source.',
            'Cargo fingerprint lookup in property-runner.py is local build plumbing; each QA manifest also preserves the resolved rustc command and --extern paths for a direct replay.',
        ],
    }

