// --- assignability (not an upstream test) -----------------------------------
//
// The rule that decides whether the typed expression is used: the equivalent
// of the runtime's "is assignable to" for value types.

#[test]
fn value_type_assignability_follows_the_managed_rules() {
    let of = ValueType::of::<String>;
    ValueTypes::register_reference::<ViewModel>();

    // Identity, "any value" and nullable wrapping.
    assert!(ValueTypes::is_assignable(of(), of()));
    assert!(ValueTypes::is_assignable(of(), ValueType::object()));
    assert!(ValueTypes::is_assignable(ValueType::of::<f64>(), ValueType::object()));
    assert!(ValueTypes::is_assignable(of(), ValueType::of::<Option<String>>()));
    assert!(!ValueTypes::is_assignable(ValueType::of::<Option<String>>(), of()));
    assert!(!ValueTypes::is_assignable(ValueType::object(), of()));

    // Conversions are not assignability.
    assert!(!ValueTypes::is_assignable(ValueType::of::<i32>(), ValueType::of::<f64>()));
    assert!(!ValueTypes::is_assignable(ValueType::of::<i32>(), ValueType::of::<Option<f64>>()));
    assert!(!ValueTypes::is_assignable(of(), ValueType::of::<f64>()));
    assert!(!ValueTypes::is_assignable(ValueType::of::<f64>(), of()));

    // Handles: derived to base, also through nullable handles.
    let derived = ValueType::of::<Ref<StyledElement>>();
    let base = ValueType::of::<Ref<FerroObject>>();
    let layoutable = ValueType::of::<Ref<Layoutable>>();
    assert!(ValueTypes::is_assignable(derived, base));
    assert!(ValueTypes::is_assignable(layoutable, derived));
    assert!(ValueTypes::is_assignable(layoutable, ValueType::of::<Option<Ref<StyledElement>>>()));
    assert!(ValueTypes::is_assignable(ValueType::of::<Option<Ref<Layoutable>>>(), ValueType::of::<Option<Ref<FerroObject>>>()));
    assert!(!ValueTypes::is_assignable(base, derived));
    assert!(!ValueTypes::is_assignable(ValueType::of::<Option<Ref<Layoutable>>>(), derived));

    // Model references.
    assert!(ValueTypes::is_assignable(ValueType::of::<Rc<ViewModel>>(), ValueType::of::<Option<Rc<ViewModel>>>()));
    assert!(!ValueTypes::is_assignable(ValueType::of::<Option<Rc<ViewModel>>>(), ValueType::of::<Rc<ViewModel>>()));
}

#[test]
fn value_type_cast_produces_exactly_the_target_type() {
    let cast = |value: BoxedValue, target: ValueType| ValueTypes::try_cast(&value, target);

    let value = cast(boxed(s("a")), ValueType::of::<Option<String>>()).unwrap();
    assert_eq!(value.downcast_ref::<Option<String>>(), Some(&Some(s("a"))));

    // A nullable value is null or its contents as "any value".
    let value = cast(boxed(Some(s("a"))), ValueType::object()).unwrap();
    let inner = value.downcast_ref::<Option<BoxedValue>>().unwrap().clone().unwrap();
    assert_eq!(inner.downcast_ref::<String>(), Some(&s("a")));
    let value = cast(boxed(Option::<String>::None), ValueType::object()).unwrap();
    assert!(value.downcast_ref::<Option<BoxedValue>>().unwrap().is_none());

    // Handles are cast to base handles, never to derived ones.
    let element: Ref<Layoutable> = TextBlock::new().upcast();
    let value = cast(boxed(Some(element.clone())), ValueType::of::<Option<Ref<StyledElement>>>()).unwrap();
    assert!(value.downcast_ref::<Option<Ref<StyledElement>>>().unwrap().is_some());
    let value = cast(boxed(Option::<Ref<Layoutable>>::None), ValueType::of::<Option<Ref<StyledElement>>>()).unwrap();
    assert!(value.downcast_ref::<Option<Ref<StyledElement>>>().unwrap().is_none());
    let root: Ref<FerroObject> = element.upcast();
    assert!(cast(boxed(root), ValueType::of::<Ref<StyledElement>>()).is_none());

    // Conversions are not casts.
    assert!(cast(boxed(1i32), ValueType::of::<f64>()).is_none());
    assert!(cast(boxed(s("1")), ValueType::of::<i32>()).is_none());
    assert!(cast(boxed(1i32), ValueType::of::<String>()).is_none());
}

// --- not from upstream: what a recycled target sees --------------------------
//
// A container that is recycled loses its item (the data context), then its
// bindings, and gets the next item and bindings of the same descriptions.
// These tests record the values the target takes on the way.

/// Records the values the text of `target` takes.
fn record_text(target: &TextBlock) -> Rc<RefCell<Vec<Option<String>>>> {
    let values: Rc<RefCell<Vec<Option<String>>>> = Rc::new(RefCell::new(Vec::new()));
    let text = TextBlock::text_property().id();
    let recorded = values.clone();
    target.property_changed(move |e| {
        if e.property().id() == text {
            recorded.borrow_mut().push(e.get_new_value::<Option<String>>());
        }
    });
    values
}

#[test]
fn recycled_target_takes_the_same_values_from_a_typed_and_an_untyped_binding() {
    for typed in [true, false] {
        let first = ViewModel::with_string("first");
        let second = ViewModel::with_string("second");
        let target = TextBlock::with_data_context(Some(&first));
        let values = record_text(&target);

        assert_expression_type(typed, &target.bind_binding(TextBlock::text_property(), &create_string_binding(typed)));
        assert_eq!(first.property_changed_subscription_count(), 1);

        // Cleared: the item leaves, then the binding.
        target.set_data_context(None);
        assert_eq!(first.property_changed_subscription_count(), 0);
        target.clear_value(TextBlock::text_property());

        // Prepared: the next item arrives, then a binding of the same
        // description.
        target.set_data_context(Some(second.clone() as BoxedValue));
        assert_expression_type(typed, &target.bind_binding(TextBlock::text_property(), &create_string_binding(typed)));
        second.set_string_value(Some(s("changed")));

        // The item that left no longer reaches the target.
        first.set_string_value(Some(s("stale")));

        // Clearing the value does not end a binding of the local value (`ValueStore.ClearValue`
        // reevaluates without the local value and leaves the binding): the first binding
        // publishes the next item, and is replaced when the second one is made.
        assert_eq!(
            values.take(),
            vec![Some(s("first")), None, Some(s("second")), None, Some(s("second")), Some(s("changed"))]
        );
        assert_eq!(target.text(), Some(s("changed")));
        assert_eq!(first.property_changed_subscription_count(), 0);
        assert_eq!(second.property_changed_subscription_count(), 1);
    }
}

/// A binding without a path publishes the data context itself: null for no
/// data context and for a nullable value that is null, the contents of a
/// nullable value otherwise.
#[test]
fn binding_to_the_data_context_itself_follows_it_through_null_and_nullable_values() {
    let target = TextBlock::new();
    let values = record_text(&target);

    let expression = target.bind_binding(TextBlock::text_property(), &CompiledBinding::empty());
    assert!(expression.as_any().is::<BindingExpression>());
    assert_eq!(target.text(), None);

    target.set_data_context(Some(boxed(s("text"))));
    target.set_data_context(Some(boxed(Some(s("nullable")))));
    target.set_data_context(Some(boxed(Option::<String>::None)));
    target.set_data_context(Some(boxed(s("again"))));
    target.set_data_context(None);

    assert_eq!(values.take(), vec![Some(s("text")), Some(s("nullable")), None, Some(s("again")), None]);
}

/// A template binding does not follow the property of a parent its target
/// has left; when the target gets the parent back, it publishes what the
/// property is then.
#[test]
fn template_binding_publishes_what_the_parent_has_when_the_target_gets_it_back() {
    let parent = TextBlock::new();
    parent.set_text(Some("one"));
    let target = TextBlock::new();
    target.set_templated_parent(&parent);
    let values = record_text(&target);

    target.bind_binding(TextBlock::text_property(), &crate::data::TemplateBinding::new(TextBlock::text_property()));
    parent.set_text(Some("two"));

    target.set_templated_parent(Option::<Ref<FerroObject>>::None);
    parent.set_text(Some("three"));
    assert_eq!(target.text(), None);

    target.set_templated_parent(&parent);
    parent.set_text(Some("four"));

    assert_eq!(values.take(), vec![Some(s("one")), Some(s("two")), None, Some(s("three")), Some(s("four"))]);
}

// --- not from upstream: the order of a failed conversion --------------------

/// A converter that records that it ran, and fails when told to.

pub(crate) fn sample(lane: &str, count: usize) -> (i64, i64, u128) {
    use std::hint::black_box;
    use std::time::Instant;
    let a = ViewModel::with_string("A");
    let b = ViewModel::with_string("B");
    let target = create_target(Some(&a), BindingMode::TwoWay);
    let initial = a.string_value_set_count.get();
    let mut checksum = 0i64;
    let wall = Instant::now();
    let start = crate::boxed_timing::thread_cpu_ns();
    match lane {
        "typed_notify" => for i in 0..count {
            a.set_string_value(Some(s(if i % 2 == 0 { "B" } else { "A" })));
            checksum += black_box(target.text().unwrap()).as_bytes()[0] as i64;
        },
        "typed_writeback" => for i in 0..count {
            target.set_text(Some(if i % 2 == 0 { "B" } else { "A" }));
            checksum += black_box(a.string_value().unwrap()).as_bytes()[0] as i64;
        },
        "typed_context" => for i in 0..count {
            target.set_data_context(Some(if i % 2 == 0 { b.clone() } else { a.clone() }));
            checksum += black_box(target.text().unwrap()).as_bytes()[0] as i64;
        },
        _ => unreachable!(),
    }
    let cpu = crate::boxed_timing::thread_cpu_ns() - start;
    let wall = wall.elapsed().as_nanos();
    assert_eq!(checksum, (65 + 66) * count as i64 / 2);
    assert_eq!(target.text().as_deref(), Some("A"));
    assert_eq!(a.string_value().as_deref(), Some("A"));
    assert_eq!(a.property_changed_subscription_count(), 1);
    assert_eq!(b.property_changed_subscription_count(), 0);
    let expected = if lane == "typed_context" { 0 } else { count as i32 };
    assert_eq!(a.string_value_set_count.get() - initial, expected);
    (checksum, cpu, wall)
}

