// Properties declared in several places.

test_class!(RegParts: FerroObject);

ferro_properties! {
    impl RegParts, also [RegParts::register_more_properties] {
        pub fn one_property() -> StyledProperty<i32> {
            FerroProperty::register::<RegParts, _>("One", 1)
        }
