//! Catch a typed panic through public property validation, verify nested Rust
//! destruction, then reuse the same property store and binding route.
use ferroui_base::*;
use ferroui_base::data::BindingPriority;
use ferroui_base::reactive::{IObserver, LightweightSubject};
use std::{cell::RefCell, rc::Rc};

#[derive(Debug, PartialEq)]
struct Payload(u32);
struct Guard<'a>(&'a Rc<RefCell<Vec<u8>>>, u8);
impl Drop for Guard<'_> {
    fn drop(&mut self) { self.0.borrow_mut().push(self.1); }
}
#[cold]
#[inline(never)]
fn fail(log: &Rc<RefCell<Vec<u8>>>) -> ! {
    let _inner = Guard(log, 2);
    std::panic::panic_any(Payload(0x496));
}
#[inline(never)]
fn set_invalid(object: &FerroObject, property: &'static StyledProperty<i32>, log: &Rc<RefCell<Vec<u8>>>) {
    let _outer = Guard(log, 1);
    object.set_value(property, -1);
}
fn main() {
    let log = Rc::new(RefCell::new(Vec::new()));
    let trace = log.clone();
    let property = FerroProperty::register_with::<FerroObject, _>(
        "UnwindCompatibility", StyledPropertyOptions::new(7).validate(move |value| {
            if *value < 0 { fail(&trace); }
            true
        }),
    );
    let object = FerroObject::new();
    let hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| set_invalid(&object, property, &log)));
    std::panic::set_hook(hook);
    let payload = result.expect_err("the validator must unwind").downcast::<Payload>().expect("typed panic payload");
    assert_eq!(*payload, Payload(0x496));
    assert_eq!(log.borrow().as_slice(), [2, 1]);
    assert_eq!(object.get_value(property), 7);
    object.set_value(property, 19);
    assert_eq!(object.get_value(property), 19);
    object.clear_value(property);
    let source = Rc::new(LightweightSubject::<i32>::new());
    let binding = object.bind(property, source.clone(), BindingPriority::Style);
    source.on_next(31);
    assert_eq!(object.get_value(property), 31);
    binding.dispose();
    assert_eq!(object.get_value(property), 7);
    println!("typed payload, nested cleanup, property-store reuse and binding reuse: ok");
}

