#!/usr/bin/env python3
"""Longer existing-binary conversion measurements with a same-image control."""
import argparse
import hashlib
import itertools
import json
import os
from pathlib import Path
import random
import statistics
import subprocess
import time


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def ratio(candidate, reference):
    values = [a / b for a, b in zip(candidate, reference)]
    rng = random.Random(9961)
    draws = sorted(statistics.median(rng.choices(values, k=len(values))) for _ in range(7000))
    return {"median": statistics.median(values), "bootstrap_95_percent": [draws[175], draws[6824]]}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument("--cpu", type=int, required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--pairs", type=int, default=31)
    parser.add_argument("--iterations", type=int, default=5_000_000)
    parser.add_argument("--lane", action="append", choices=("boxed_wrong", "boxed_live", "borrowed_wrong"),
                        help="lane to measure (repeatable); default preserves the original two-lane protocol")
    args = parser.parse_args()
    prior = json.loads(args.manifest.read_text())
    artifacts = {}
    for label in ("reference", "candidate"):
        record = prior["builds"][label]["registration"]
        command = record["identity"]["command"]
        binary = Path(command[command.index("-o") + 1])
        assert sha(binary) == record["sha256"], binary
        artifacts[label] = {"path": str(binary), "sha256": record["sha256"]}
    artifacts["reference_control"] = dict(artifacts["reference"])
    os.sched_setaffinity(0, {args.cpu})
    env = dict(os.environ)
    env.pop("LLVM_PROFILE_FILE", None)
    lanes = args.lane or ["boxed_wrong", "boxed_live"]
    if len(lanes) != len(set(lanes)):
        parser.error("each --lane may only be selected once")
    orders = list(itertools.permutations(artifacts))
    raw = {lane: [] for lane in lanes}
    started = time.monotonic()
    for block in range(-3, args.pairs):
        order = orders[block % len(orders)]
        for lane in (lanes if block % 2 == 0 else list(reversed(lanes))):
            row = {"block": block, "order": list(order), "results": {}}
            for label in order:
                command = [artifacts[label]["path"], lane, str(args.iterations)]
                output = subprocess.check_output(command, env=env, text=True)
                actual, operations, checksum, cpu, wall = output.split()
                operations, checksum, cpu, wall = map(int, (operations, checksum, cpu, wall))
                assert actual == lane and operations == args.iterations and checksum == args.iterations, output
                assert cpu > 0 and wall > 0, output
                row["results"][label] = {"operations": operations, "checksum": checksum,
                                          "thread_cpu_ns": cpu, "wall_ns": wall}
            if block >= 0:
                raw[lane].append(row)
    comparisons = {}
    for lane in lanes:
        comparisons[lane] = {}
        for metric in ("thread_cpu_ns", "wall_ns"):
            samples = {label: [row["results"][label][metric] / args.iterations for row in raw[lane]]
                       for label in artifacts}
            comparisons[lane][metric] = {
                "medians_ns_per_operation": {label: statistics.median(values) for label, values in samples.items()},
                "candidate_reference": ratio(samples["candidate"], samples["reference"]),
                "candidate_reference_control": ratio(samples["candidate"], samples["reference_control"]),
                "same_image_control_reference": ratio(samples["reference_control"], samples["reference"]),
            }
    report = {
        "method": "Focused follow-up to the rejected-boxed and isolated borrowed-miss signals. Existing unmodified binaries, three warmup blocks, explicitly recorded lanes and operation count, all six orders of candidate/reference/same-image reference control, alternating lane order. Same-image control runs the exact reference executable as a separate fresh process. This supplements rather than replaces the original rotated short-process cohorts. No profile training or source change.",
        "lanes": lanes,
        "source": {"path": str(Path(__file__).resolve()), "sha256": sha(__file__)},
        "manifest": {"path": str(args.manifest), "sha256": sha(args.manifest)},
        "cpu": args.cpu, "blocks": args.pairs, "iterations": args.iterations,
        "elapsed_seconds": time.monotonic() - started, "artifacts": artifacts,
        "raw": raw, "comparisons": comparisons,
    }
    args.out.write_text(json.dumps(report, indent=2) + "\n")
    print(json.dumps(comparisons, indent=2))


if __name__ == "__main__":
    main()

