impl Work {
 fn setup()->Self {let varied=Node::varied();varied.override_default_value::<Branch>(29);varied.override_default_value::<Sibling>(31);let hosts=[Node::object(),Branch::object(),Leaf::object(),Sibling::object()];for (i,h) in hosts.iter().enumerate() {h.set_value(Node::local(),100+i as i32);}
 Self {hosts,plain:Node::plain(),scoped:Node::scoped(),varied,local:Node::local()}}
 #[inline(never)] fn execute(&self,lane:Lane,steps:usize)->i64 {
