 Lane::MetaScoped=> read!(|i:usize| *self.scoped.get_metadata_for(black_box(&self.hosts[order[i&15]])).default_value()),
 Lane::MetaOverride=>read!(|_:usize| *self.varied.get_metadata_for(black_box(&self.hosts[2])).default_value()),
