   }
 }
 Lane::StyledBinding=> {
   let host=black_box(&self.hosts[2]);
   let source=Rc::new(LightweightSubject::<i32>::new());
   let lease=host.bind(self.varied,source.clone(),BindingPriority::Style);
   for i in 0..steps {source.on_next((i&1023) as i32);sum+=host.get_value(self.varied) as i64;}
