 }
}
fn main(){let round:usize=std::env::args().nth(1).unwrap().parse().unwrap();let n=200_000;ferroui_base::register_types(); assert!(black_box(TypeInfo::registered_types().len())>100);let w=Work::setup();let lanes=[Lane::MetaPlain,Lane::MetaScoped,Lane::MetaOverride,Lane::GetPlain,Lane::GetOverride,Lane::GetMixedHost,Lane::GetEffective,Lane::MixedReadWrite,Lane::StyleInstallDispose,Lane::StyledBinding,Lane::Coercion];
